#include "models/LostFoundPost.h"
#include <cstdint>
#include <istream>
#include <ostream>
#include <stdexcept>
using namespace std;
static void lf_put(ostream& o,const string& s){if(s.size()>1000000)throw runtime_error("Text too long");uint32_t n=static_cast<uint32_t>(s.size());o.write(reinterpret_cast<const char*>(&n),4);o.write(s.data(),n);if(!o)throw runtime_error("Write failed");}
static string lf_get(istream& i){uint32_t n=0;i.read(reinterpret_cast<char*>(&n),4);if(!i||n>1000000)throw runtime_error("Invalid text length");string s(n,'\0');if(n)i.read(&s[0],n);if(!i)throw runtime_error("Read failed");return s;}
LostFoundPost::LostFoundPost():Post(),is_lost_(true),item_name_(),location_(),contact_info_(),image_path_(),is_resolved_(false){}
LostFoundPost::LostFoundPost(int a,const Time& t,const string& c,bool lost,const string& item,const string& loc,const string& contact,const string& image):Post(a,t,c),is_lost_(lost),item_name_(item),location_(loc),contact_info_(contact),image_path_(image),is_resolved_(false){}
string LostFoundPost::type_name()const{return "LostFound";}string LostFoundPost::search_text()const{return caption()+" "+item_name_+" "+location_+" "+contact_info_+(is_lost_?" lost":" found");}float LostFoundPost::render_height(float w)const{return w>0?72.0f+(image_path_.empty()?0:w):0;}
void LostFoundPost::draw(DrawContext& c,const Rectangle& r)const{(void)c;(void)r;}void LostFoundPost::draw(DrawContext& c,float x,float y,float w)const{(void)c;(void)x;(void)y;(void)w;}bool LostFoundPost::handle_click(float mx,float my,float x,float y,float w,int v){(void)my;(void)y;(void)v;return mx>=x&&mx<=x+w;}
bool LostFoundPost::is_lost()const{return is_lost_;}void LostFoundPost::set_is_lost(bool b){is_lost_=b;}const string& LostFoundPost::item_name()const{return item_name_;}void LostFoundPost::set_item_name(const string& s){item_name_=s;}const string& LostFoundPost::location()const{return location_;}void LostFoundPost::set_location(const string& s){location_=s;}const string& LostFoundPost::contact_info()const{return contact_info_;}void LostFoundPost::set_contact_info(const string& s){contact_info_=s;}const string& LostFoundPost::image_path()const{return image_path_;}void LostFoundPost::set_image_path(const string& s){image_path_=s;}bool LostFoundPost::is_resolved()const{return is_resolved_;}void LostFoundPost::set_resolved(bool b){is_resolved_=b;}
void LostFoundPost::write(ostream& o)const{Post::write(o);uint8_t lost=is_lost_,resolved=is_resolved_;o.write(reinterpret_cast<const char*>(&lost),1);lf_put(o,item_name_);lf_put(o,location_);lf_put(o,contact_info_);lf_put(o,image_path_);o.write(reinterpret_cast<const char*>(&resolved),1);if(!o)throw runtime_error("Write failed");}
void LostFoundPost::read(istream& in){Post::read(in);uint8_t lost=0,resolved=0;in.read(reinterpret_cast<char*>(&lost),1);if(!in||lost>1)throw runtime_error("Invalid lost flag");string item=lf_get(in),loc=lf_get(in),contact=lf_get(in),image=lf_get(in);in.read(reinterpret_cast<char*>(&resolved),1);if(!in||resolved>1)throw runtime_error("Invalid resolved flag");is_lost_=lost!=0;item_name_.swap(item);location_.swap(loc);contact_info_.swap(contact);image_path_.swap(image);is_resolved_=resolved!=0;}
